window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b1cb5c93cc3dc925"]={"versions": [{"id": "FIG-b1cb5c93cc3dc925", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR ECU Configuration Description (AUTOSAR_TPS_ECUConfiguration). Es definiert das Metamodell für Konfigurations-Container (<code>EcucParamConfContainerDef</code>) und deren hierarchische sowie strukturelle Zusammensetzung aus Untercontainern, Auswahlcontainern, Parametern und Referenzen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>EcucContainerDef</strong> (spezialisiert <code>EcucDefinitionElement</code>): Abstrakte Basisklasse für Container-Definitionen mit dem optionalen Attribut <code>postBuildChangeable: Boolean [0..1]</code>.</li>\n<li><strong>EcucParamConfContainerDef</strong> (spezialisiert <code>EcucContainerDef</code>): Konkrete Container-Definition mit Attribut <code>multipleConfigurationContainer: Boolean</code>.</li>\n<li>Besitzt per Komposition über Rolle <code>+subContainer</code> mit Multiplizität <code>*</code> übergeordnete/verschachtelte <code>EcucContainerDef</code>.</li>\n<li>Besitzt per Komposition über Rolle <code>+choice</code> mit Multiplizität <code>*</code> Elemente des Typs <code>EcucChoiceContainerDef</code>.</li>\n<li>Besitzt per Komposition über Rolle <code>+parameter</code> mit Multiplizität <code>*</code> Elemente des Typs <code>EcucParameterDef</code>.</li>\n<li>Besitzt per Komposition über Rolle <code>+reference</code> mit Multiplizität <code>*</code> Elemente des Typs <code>EcucAbstractReferenceDef</code>.</li>\n<li><strong>EcucChoiceContainerDef</strong> (spezialisiert <code>EcucContainerDef</code>): Dient der Definition alternativer Container-Optionen.</li>\n<li><strong>EcucCommonAttributes</strong> (spezialisiert <code>EcucDefinitionElement</code>): Definiert gemeinsame Attribute mit <code>origin: String</code> und <code>requiresIndex: Boolean [0..1]</code>.</li>\n<li><strong>EcucParameterDef</strong> (spezialisiert <code>EcucCommonAttributes</code>): Parameter-Definition mit Attributen <code>symbolicNameValue: Boolean</code> und <code>withAuto: Boolean [0..1]</code>.</li>\n<li><strong>EcucAbstractReferenceDef</strong> (spezialisiert <code>EcucCommonAttributes</code>): Abstrakte Definition von Referenzen zwischen Konfigurationselementen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell. Es modelliert keine Laufzeit- oder Sequenzabläufe, sondern statische Typdefinitionen, Generalisierungen und Kompositionshierarchien für Generatoren und Konfigurationswerkzeuge im AUTOSAR-Entwicklungsprozess.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Konfigurationswerkzeuge (ECU Configuration Editors und Codegeneratoren). <code>EcucParamConfContainerDef</code> strukturiert BSW- und RTE-Modulkonfigurationen. <code>postBuildChangeable</code> definiert, ob Werte nach der Kompilierung zur Post-Build-Laufzeit änderbar sind. <code>multipleConfigurationContainer</code> steuert das Vorhandensein in multiplen Konfigurationssätzen (Post-Build Selectable/Loadable).</p>"}, {"id": "FIG-3d273b148386ae65", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR ECU Configuration Description (AUTOSAR_TPS_ECUConfiguration). Es definiert das Metamodell für Konfigurations-Container (<code>EcucParamConfContainerDef</code>) und deren hierarchische sowie strukturelle Zusammensetzung aus Untercontainern, Auswahlcontainern, Parametern und Referenzen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>EcucContainerDef</strong> (spezialisiert <code>EcucDefinitionElement</code>): Abstrakte Basisklasse für Container-Definitionen mit den Attributen <code>postBuildChangeable: Boolean [0..1]</code> und <code>requiresIndex: Boolean [0..1]</code>.</li>\n<li><strong>EcucParamConfContainerDef</strong> (spezialisiert <code>EcucContainerDef</code>): Konkrete Container-Definition mit Attribut <code>multipleConfigurationContainer: Boolean</code>.</li>\n<li>Besitzt per Komposition über Rolle <code>+subContainer</code> mit Multiplizität <code>*</code> übergeordnete/verschachtelte <code>EcucContainerDef</code>.</li>\n<li>Besitzt per Komposition über Rolle <code>+choice</code> mit Multiplizität <code>*</code> Elemente des Typs <code>EcucChoiceContainerDef</code>.</li>\n<li>Besitzt per Komposition über Rolle <code>+parameter</code> mit Multiplizität <code>*</code> Elemente des Typs <code>EcucParameterDef</code>.</li>\n<li>Besitzt per Komposition über Rolle <code>+reference</code> mit Multiplizität <code>*</code> Elemente des Typs <code>EcucAbstractReferenceDef</code>.</li>\n<li><strong>EcucChoiceContainerDef</strong> (spezialisiert <code>EcucContainerDef</code>): Dient der Definition alternativer Container-Optionen.</li>\n<li><strong>EcucCommonAttributes</strong> (spezialisiert <code>EcucDefinitionElement</code>): Definiert gemeinsame Attribute mit <code>origin: String</code> und <code>requiresIndex: Boolean [0..1]</code>.</li>\n<li><strong>EcucParameterDef</strong> (spezialisiert <code>EcucCommonAttributes</code>): Parameter-Definition mit Attributen <code>symbolicNameValue: Boolean</code> und <code>withAuto: Boolean [0..1]</code>.</li>\n<li><strong>EcucAbstractReferenceDef</strong> (spezialisiert <code>EcucCommonAttributes</code>): Abstrakte Definition von Referenzen zwischen Konfigurationselementen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell. Es modelliert keine Laufzeit- oder Sequenzabläufe, sondern statische Typdefinitionen, Generalisierungen und Kompositionshierarchien für Generatoren und Konfigurationswerkzeuge im AUTOSAR-Entwicklungsprozess.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Konfigurationswerkzeuge (ECU Configuration Editors und Codegeneratoren). <code>EcucParamConfContainerDef</code> strukturiert BSW- und RTE-Modulkonfigurationen. <code>postBuildChangeable</code> legt die Änderbarkeit zur Post-Build-Zeit fest. <code>requiresIndex</code> bestimmt für Container bzw. Parameter und Referenzen, ob Indizes zur eindeutigen Unterscheidung und Adressierung mehrfacher Instanzen erforderlich sind. <code>multipleConfigurationContainer</code> steuert das Vorhandensein in multiplen Konfigurationssätzen (Post-Build Selectable/Loadable).</p>"}], "trans": [{"from": "FIG-b1cb5c93cc3dc925", "to": "FIG-3d273b148386ae65", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>EcucContainerDef</code>: Attribut <code>+ requiresIndex: Boolean [0..1]</code> ergänzt.</li>\n<li><code>EcucParamConfContainerDef</code>, <code>EcucContainerDef</code>, <code>EcucCommonAttributes</code>, <code>EcucParameterDef</code>: Formatierung der Typangaben bei Attributen von <code>: Typ</code> auf <code>:Typ</code> bzw. Leerzeichen vor dem Doppelpunkt vereinheitlicht/angepasst.</li>\n</ul>"}]};
